-- The Scramble for Africa scenario City-States have existing Civilopedia entries in the BNW files, but they are much shorter and less detailed
-- For parity with their peers, we edit and expand on those as well
UPDATE Language_ru_RU
SET Text = 'Нгазаргаму был основан в конце XV века маем Али Гаджи как столица империи Канем-Борну. Расположенный к западу от озера Чад на территории современного северо-востока Нигерии, город помог вновь объединить империю после поколений династических конфликтов и переселения из прежнего ядра в Канеме. Положение рядом с плодородными землями и караванными путями через Кавар и Феццан позволило Нгазаргаму стать одним из главных политических и торговых центров центрального Сахеля.[NEWLINE][NEWLINE]Укреплённый город процветал благодаря земледелию, региональным рынкам и транссахарской торговле. Купцы торговали порабощёнными пленниками, натроном, тканями, кожами, слоновой костью, лошадьми, огнестрельным оружием, медью и предметами роскоши, двигавшимися между озером Чад, страной хауса и Северной Африкой. Нгазаргаму достиг высшего расцвета при Идрисе Алооме в конце XVI века, когда армия и администрация Борну были укреплены, а связи расширились до османского Триполи и других исламских центров. Более трёх столетий город оставался главной резиденцией правителей Сайфава и сердцем их империи.[NEWLINE][NEWLINE]В 1808 году силы джихада фульбе захватили и разрушили Нгазаргаму, вынудив императорский двор покинуть город. Мухаммад аль-Амин аль-Канеми позднее организовал оборону Борну, но ни правители Сайфава, ни его преемники уже не восстановили старую столицу надолго. Политическая власть сместилась в новые центры, такие как Кафела и Кукава, а Нгазаргаму превратился в руины. Его сохранившиеся земляные валы рядом с современным Гейдамом напоминают об одной из самых долговечных имперских столиц в истории Африки.'
WHERE Tag = 'TXT_KEY_CIV5_BORNU_TEXT';

UPDATE Language_ru_RU
SET Text = 'В конце XIX века Мсири, честолюбивый сын восточноафриканского купца, основал город Бункея на территории нынешней провинции Катанга в Демократической Республике Конго. Отсюда он создал королевство Байеке, подчинив себе обширные земли восточной части бассейна Конго. Бункея стала важным торговым центром, через который шли слоновая кость, медь, железная руда, соль и рабы к арабо-суахилийским купцам на побережье. В обмен Мсири получал огнестрельное оружие и боеприпасы, что укрепляло его власть и способствовало дальнейшему расширению государства.[NEWLINE][NEWLINE]К 1880-м годам Бункея привлекла внимание европейских держав. Британцы рассматривали возможность союза с Мсири, что заставило короля Леопольда II Бельгийского действовать быстро, чтобы закрепить регион за своим Свободным государством Конго. Леопольд отправил к Бункее три экспедиции, и первые две так и не добились подчинения Мсири.[NEWLINE][NEWLINE]В 1891 году третья экспедиция, выступившая с Занзибара, вынудила силы Байеке отступить. Вскоре после этого Мсири был убит во время столкновения, а Бункея вошла в состав Свободного государства Конго. Это ознаменовало конец одного из последних крупных коренных государств Центральной Африки, сопротивлявшихся европейскому колониальному захвату.'
WHERE Tag = 'TXT_KEY_CIV5_BUNKEYA_TEXT';

UPDATE Language_ru_RU
SET Text = 'Леалуи был основан как столица Баротселенда в 1878 году Литунгой Леваникой, правителем народа лози. Построенный в пойме Баротсе верхней Замбези на территории современной западной Замбии, он стал резиденцией царского двора после периода династических конфликтов. Его дворец, дома знати и церемониальные площадки образовали политическое сердце королевства, чьё влияние распространялось на большую часть бассейна верхней Замбези.[NEWLINE][NEWLINE]Жизнь в Леалуи определялась ежегодными разливами равнины. Каналы и водные пути связывали общины по всему болотистому краю, перевозили людей и товары между поселениями и делали столицу естественным центром регионального обмена. Рыболовство, скотоводство и земледелие на осушающихся после паводка землях поддерживали эту торговлю, а Литунга и его чиновники управляли землями и водами королевства из Леалуи.[NEWLINE][NEWLINE]В 1890 году Леваника подписал концессию Лохнера с Британской Южно-Африканской компанией, стремясь получить защиту от соседних держав. Соглашение предоставляло широкие торговые и минеральные права и помогло открыть путь к постепенному установлению британской колониальной власти над Баротселендом. Тем не менее Леалуи остался главной царской столицей и сохранил значительное политическое и церемониальное значение.'
WHERE Tag = 'TXT_KEY_CIV5_LUBA_TEXT';

UPDATE Language_ru_RU
SET Text = 'Племена нинси Верхней Вольты долгое время были разобщены враждой и войнами, пока в 1441 году полулегендарный воин Вурби не объединил их. Эта победа положила начало империи Мосси, столицей которой стал Вогодого — позднее известный во французской форме как Уагадугу. Расположенный на перекрёстке региональных торговых путей, Уагадугу притягивал купцов со всей Западной Африки, а также караваны, шедшие как с Атлантики, так и из Сахеля.[NEWLINE][NEWLINE]На протяжении веков мосси успешно отражали натиск могущественных соседей, включая империи Сонгай и Мали, продолжая при этом торговать золотом, солью и тканями. Уагадугу вырос в космополитический центр управления, где императорский двор сочетал традиции мосси с исламскими влияниями, принесёнными торговцами и учёными.[NEWLINE][NEWLINE]В 1896 году французские колониальные войска под командованием Поля Вуле и Жюльена Шануана вторглись в регион, стремясь завершить объединение французских владений в Западной Африке. Мосси были побеждены, и Уагадугу вошёл в состав Французской Западной Африки. После обретения независимости в 1960 году он стал столицей Республики Верхняя Вольта, позднее переименованной в Буркина-Фасо, сохранив роль политического и культурного сердца страны.'
WHERE Tag = 'TXT_KEY_CIV5_OUGADOUGOU_TEXT';

UPDATE Language_ru_RU
SET Text = 'Основанный народом сонинке примерно в XI веке н. э., Сегу со временем стал заметным центром земледелия и торговли на берегах Нигера. Плодородные земли поддерживали сельское хозяйство и рыболовство, а рынки связывали город с такими великими центрами, как Дженне и Тимбукту. Первый золотой век Сегу пришёлся на правление Битона Кулибали (1712-1755), превратившего его в столицу государства бамбара.[NEWLINE][NEWLINE]Дисциплинированная армия Битона и его административные реформы укрепили власть Сегу над окружающими землями. При Мамари Кулибали Сегу объединился с Дженне и Масиной, образовав мощный союз, господствовавший в среднем течении Нигера. Город прославился ремеслом и учёностью, а его мастера создавали прекрасные ткани и изделия из металла.[NEWLINE][NEWLINE]Около 1860 года город пал перед Эль-Хадж Умаром Таллем — тукулёрским завоевателем и исламским реформатором, обратившим население в ислам. В 1890-х годах сюда пришли французские колониальные войска, включив Сегу в свою растущую западноафриканскую империю. Французы сделали Сегу административным центром ирригационного проекта Office du Niger, закрепив его значение как регионального узла.'
WHERE Tag = 'TXT_KEY_CIV5_SEGOU_TEXT';

UPDATE Language_ru_RU
SET Text = 'Сокото расположен чуть выше слияния рек Сокото и Рима на северо-западе современной Нигерии. Город был основан в 1809 году Мухаммадом Белло как укреплённое военное и религиозное поселение во время джихада, возглавленного его отцом Усманом дан Фодио. После смерти Усмана в 1817 году Сокото стал резиденцией Белло и главной столицей Сокотского халифата, тогда как Гванду служил важным западным центром управления.[NEWLINE][NEWLINE]В начале XIX века Сокото стал политическим и интеллектуальным сердцем одного из крупнейших государств Африки. Его правители управляли широкой сетью эмиратов через религиозный авторитет, назначенных чиновников, налоги и дань, а учёные развивали влиятельную традицию исламского права, богословия и образования. Особенно Сокото процветал при Мухаммаде Белло, чьё правление укрепило администрацию и закрепило за городом положение старшей столицы халифата.[NEWLINE][NEWLINE]Шотландский путешественник Хью Клаппертон стал первым документально известным европейским посетителем Сокото в 1824 году и умер неподалёку от города во время второго визита в 1827 году. Британские войска захватили Сокото в 1903 году, положив конец суверенитету халифата и включив город в состав Протектората Северная Нигерия. Британцы сохранили султана Сокото и большую часть эмиратской структуры в рамках косвенного управления, что позволило городу остаться важным центром исламского авторитета.'
WHERE Tag = 'TXT_KEY_CIV5_SOKOTO_TEXT';

